<?php require __DIR__.'/../includes/admin.php'; $a=require_admin(); $stats=[]; foreach(['players'=>"SELECT COUNT(*) FROM users WHERE role='player'",'tournaments'=>"SELECT COUNT(*) FROM tournaments",'pending'=>"SELECT COUNT(*) FROM topup_requests WHERE status='pending'",'coins'=>"SELECT COALESCE(SUM(coins),0) FROM users"] as $k=>$sql)$stats[$k]=(int)$pdo->query($sql)->fetchColumn(); $tab=$_GET['tab']??'dashboard'; $tabs=['dashboard','payments','tournaments','players','ledger','tickets','audit','settings']; if(!in_array($tab,$tabs,true))$tab='dashboard'; $csrf=csrf_token(); ?>
