abel class="text-sm">Minimum top-up (₹)<input type="number" min="0" name="min_topup_rupees" value="<?=h($settings['min_topup_rupees'])?>" class="block w-full mt-1 bg-slate-800 rounded-lg p-3"></label><label class="text-sm md:col-span-2">Home announcement<textarea name="home_notice" maxlength="1000" class="block w-full mt-1 bg-slate-800 rounded-lg p-3"><?=h($settings['home_notice'])?></textarea></label><div class="md:col-span-2 flex flex-wrap gap-5 text-sm"><label class="flex items-center gap-2"><input type="checkbox" name="registration_enabled" value="1" <?=$settings['registration_enabled']==='1'?'checked':''?>> Registrations enabled</label><label class="flex items-center gap-2"><input type="checkbox" name="maintenance_mode" value="1" <?=$settings['maintenance_mode']==='1'?'checked':''?>> Maintenance mode</label></div><button class="bg-violet-600 rounded-lg px-5 py-3 md:col-span-2">Save settings</button></form></section><?php endif?></main></div></body></html>
